import math

class Solution:
    def minimizedMaximum(self, n: int, quantities: list[int]) -> int:
        lo, hi = 1, max(quantities)
        while lo < hi:
            mid = (lo + hi) // 2
            stores_needed = sum(math.ceil(q / mid) for q in quantities)
            if stores_needed <= n:
                hi = mid
            else:
                lo = mid + 1
        return lo

